// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SiteMessage) predicate.SiteMessage {
	return predicate.SiteMessage(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SiteMessage) predicate.SiteMessage {
	return predicate.SiteMessage(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SiteMessage) predicate.SiteMessage {
	return predicate.SiteMessage(sql.NotPredicates(p))
}
